mapper.select:
SELECT sct.sctid, s.sname, c.cname, t.tname, sct.grade, ct.term
FROM student_course_teacher sct
JOIN student s ON sct.sid = s.sid
JOIN course_teacher ct ON sct.ctid = ct.ctid
JOIN course c ON ct.cid = c.cid
JOIN teacher t ON ct.tid = t.tid
WHERE sct.deleted = 0
AND sct.sid = #{sid}


        AND s.sname LIKE CONCAT('%', #{sname}, '%')
        AND s.sname = #{sname}


AND ct.cid = #{cid}


        AND c.cname LIKE CONCAT('%', #{cname}, '%')
        AND c.cname = #{cname}


AND ct.tid = #{tid}


        AND t.tname LIKE CONCAT('%', #{tname}, '%')
        AND t.tname = #{tname}


AND sct.grade >= #{lowBound}
AND sct.grade <= #{highBound}
AND ct.term = #{term}

SELECT sct.* FROM student_course_teacher sct
                      JOIN course_teacher ct ON sct.ctid = ct.ctid
WHERE sct.sid = #{sct.sid}
  AND ct.cid = #{sct.cid}
  AND ct.tid = #{sct.tid}
  AND ct.term = #{sct.term}
  AND sct.deleted = 0

mapper.insert:
INSERT INTO student_course_teacher (ctid, sid)
SELECT ct.ctid, #{s.sid} FROM course_teacher ct
WHERE ct.cid = #{s.cid}
  AND ct.tid = #{s.tid}
  AND ct.term = #{s.term}

mapper.update:
UPDATE student_course_teacher sct
    JOIN course_teacher ct ON sct.ctid = ct.ctid
    SET sct.grade = #{grade}
WHERE sct.sid = #{sid}
  AND ct.cid = #{cid}
  AND ct.tid = #{tid}
  AND ct.term = #{term}

mapper.delete:
DELETE sct FROM student_course_teacher sct
JOIN course_teacher ct ON sct.ctid = ct.ctid
WHERE sct.sid = #{sct.sid}
AND ct.cid = #{sct.cid}
AND ct.tid = #{sct.tid}
